def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c
    my_d = n - my_c

    last_me, last_opp = history[-1]

    w = min(10, n)
    recent_opp = history[-w:]
    recent_opp_c = 0
    for h in recent_opp:
        if h[1] == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / w

    def_streak = 0
    for h in reversed(history):
        if h[1] == 'D':
            def_streak += 1
        else:
            break

    rounds_left = 100 - n

    if rounds_left <= 1:
        return 'D'
    if rounds_left <= 2:
        return 'D'
    if rounds_left <= 5:
        if recent_rate >= 0.7:
            return 'C'
        if recent_rate <= 0.3:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n < 2:
        return 'C'

    if opp_d == 0:
        return 'C'

    if opp_d > opp_c + 5 and n > 20:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    if my_d > opp_d + 2:
        return 'C'

    if last_opp == 'D':
        if opp_d <= 1 or recent_rate >= 0.8:
            return 'C'
        if def_streak >= 3:
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        if recent_rate >= 0.5:
            return 'C'
        if rng.random() < 0.7:
            return 'D'
        return 'C'
    else:
        return 'C'
